#!/usr/bin/env python3
import csv
import json
import sys


def main():
    if len(sys.argv) != 2:
        print("usage: stats.py <chemin.csv>", file=sys.stderr)
        return 1

    path = sys.argv[1]
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            rows = list(csv.reader(f))
    except OSError as e:
        print(f"error: {e}", file=sys.stderr)
        return 1

    if not rows:
        print("{}")
        return 0

    header = rows[0]
    columns = [[] for _ in header]
    for row in rows[1:]:
        for i in range(len(header)):
            value = row[i].strip() if i < len(row) else ""
            if value:
                columns[i].append(value)

    result = {}
    for name, values in zip(header, columns):
        numbers = []
        ok = True
        for value in values:
            try:
                numbers.append(float(value))
            except ValueError:
                ok = False
                break
        if not ok or not numbers:
            continue
        result[name] = {
            "count": len(numbers),
            "mean": sum(numbers) / len(numbers),
            "min": min(numbers),
            "max": max(numbers),
        }

    print(json.dumps(result))
    return 0


if __name__ == "__main__":
    sys.exit(main())
